export const META_CODING: CodingQuestion[] = [
  { problem: "Valid Parentheses (LeetCode 20)", difficulty: "Easy", approach: "Stack-based matching. Push opening brackets, pop and validate on closing.", solution: `function isValid(s) {\n  const stack = [];\n  const map = { ')': '(', ']': '[', '}': '{' };\n  for (const c of s) {\n    if ('([{'.includes(c)) stack.push(c);\n    else if (stack.pop() !== map[c]) return false;\n  }\n  return stack.length === 0;\n}`, complexity: "Time: O(n), Space: O(n)" },
  { problem: "Merge Intervals (LeetCode 56)", difficulty: "Medium", approach: "Sort by start time, merge overlapping intervals.", solution: `function merge(intervals) {\n  intervals.sort((a, b) => a[0] - b[0]);\n  const merged = [intervals[0]];\n  for (let i = 1; i < intervals.length; i++) {\n    const last = merged[merged.length - 1];\n    if (intervals[i][0] <= last[1]) last[1] = Math.max(last[1], intervals[i][1]);\n    else merged.push(intervals[i]);\n  }\n  return merged;\n}`, complexity: "Time: O(n log n), Space: O(n)" },
  { problem: "Clone Graph (LeetCode 133)", difficulty: "Medium", approach: "BFS/DFS with hash map to track visited nodes.", solution: `function cloneGraph(node) {\n  if (!node) return null;\n  const map = new Map();\n  const clone = n => {\n    if (map.has(n.val)) return map.get(n.val);\n    const copy = new Node(n.val);\n    map.set(n.val, copy);\n    copy.neighbors = n.neighbors.map(clone);\n    return copy;\n  };\n  return clone(node);\n}`, complexity: "Time: O(V+E), Space: O(V)" },
  { problem: "Serialize and Deserialize Binary Tree (LeetCode 297)", difficulty: "Hard", approach: "Preorder traversal with 'null' markers for reconstruction.", solution: `function serialize(root) {\n  if (!root) return 'null';\n  return root.val + ',' + serialize(root.left) + ',' + serialize(root.right);\n}\nfunction deserialize(data) {\n  const vals = data.split(',');\n  function build() {\n    const v = vals.shift();\n    if (v === 'null') return null;\n    const node = new TreeNode(Number(v));\n    node.left = build(); node.right = build();\n    return node;\n  }\n  return build();\n}`, complexity: "Time: O(n), Space: O(n)" },
  { problem: "Design Instagram Feed (System Design Coding)", difficulty: "Hard", approach: "Fan-out on write for celebrities, fan-out on read for regular users.", solution: `class NewsFeed {\n  constructor() { this.following = new Map(); this.posts = new Map(); }\n  post(userId, content) {\n    if (!this.posts.has(userId)) this.posts.set(userId, []);\n    this.posts.get(userId).push({ content, time: Date.now() });\n  }\n  follow(follower, followee) {\n    if (!this.following.has(follower)) this.following.set(follower, new Set());\n    this.following.get(follower).add(followee);\n  }\n  getFeed(userId) {\n    const feed = [];\n    for (const f of (this.following.get(userId) || []))\n      feed.push(...(this.posts.get(f) || []));\n    feed.sort((a, b) => b.time - a.time);\n    return feed.slice(0, 50);\n  }\n}`, complexity: "Time: O(F * P) per feed, Space: O(U * P)" },
  { problem: "Lowest Common Ancestor (LeetCode 236)", difficulty: "Medium", approach: "Recursive: if current node is p or q, return it. Recurse left and right.", solution: `function lca(root, p, q) {\n  if (!root || root === p || root === q) return root;\n  const left = lca(root.left, p, q);\n  const right = lca(root.right, p, q);\n  if (left && right) return root;\n  return left || right;\n}`, complexity: "Time: O(n), Space: O(h)" },
  { problem: "Word Break (LeetCode 139)", difficulty: "Medium", approach: "DP: dp[i] = true if s[0..i] can be segmented using wordDict.", solution: `function wordBreak(s, wordDict) {\n  const words = new Set(wordDict);\n  const dp = new Array(s.length + 1).fill(false);\n  dp[0] = true;\n  for (let i = 1; i <= s.length; i++)\n    for (let j = 0; j < i; j++)\n      if (dp[j] && words.has(s.slice(j, i))) { dp[i] = true; break; }\n  return dp[s.length];\n}`, complexity: "Time: O(n^2 * k), Space: O(n)" },
  { problem: "Median of Two Sorted Arrays (LeetCode 4)", difficulty: "Hard", approach: "Binary search on smaller array. Partition both arrays at mid points.", solution: `function findMedianSortedArrays(a, b) {\n  if (a.length > b.length) [a, b] = [b, a];\n  const m = a.length, n = b.length;\n  let lo = 0, hi = m;\n  while (lo <= hi) {\n    const i = (lo + hi) >> 1, j = ((m + n + 1) >> 1) - i;\n    const maxLeftA = i === 0 ? -Infinity : a[i-1];\n    const minRightA = i === m ? Infinity : a[i];\n    const maxLeftB = j === 0 ? -Infinity : b[j-1];\n    const minRightB = j === n ? Infinity : b[j];\n    if (maxLeftA <= minRightB && maxLeftB <= minRightA)\n      return (m + n) % 2 ? Math.max(maxLeftA, maxLeftB) : (Math.max(maxLeftA, maxLeftB) + Math.min(minRightA, minRightB)) / 2;\n    else if (maxLeftA > minRightB) hi = i - 1;\n    else lo = i + 1;\n  }\n}`, complexity: "Time: O(log(min(m,n))), Space: O(1)" },
  { problem: "Implement Trie (LeetCode 208)", difficulty: "Medium", approach: "Tree nodes with children map and isEnd flag.", solution: `class Trie {\n  constructor() { this.root = { children: {}, isEnd: false }; }\n  insert(word) {\n    let node = this.root;\n    for (const c of word) {\n      if (!node.children[c]) node.children[c] = { children: {}, isEnd: false };\n      node = node.children[c];\n    }\n    node.isEnd = true;\n  }\n  search(word) {\n    let node = this.root;\n    for (const c of word) { if (!node.children[c]) return false; node = node.children[c]; }\n    return node.isEnd;\n  }\n  startsWith(prefix) {\n    let node = this.root;\n    for (const c of prefix) { if (!node.children[c]) return false; node = node.children[c]; }\n    return true;\n  }\n}`, complexity: "Time: O(L) per op, Space: O(N*L)" },
  { problem: "Design TinyURL (System Design Coding)", difficulty: "Medium", approach: "Base62 encoding of auto-increment ID. HashMap for reverse lookup.", solution: `class TinyURL {\n  constructor() { this.urls = new Map(); this.counter = 0; this.chars = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'; }\n  shorten(url) {\n    let id = this.counter++;\n    let short = '';\n    while (id) { short += this.chars[id % 62]; id = Math.floor(id / 62); }\n    this.urls.set(short, url);\n    return short;\n  }\n  resolve(short) { return this.urls.get(short); }\n}`, complexity: "Time: O(1) both, Space: O(n)" },
  { problem: "Maximum Subarray (LeetCode 53)", difficulty: "Easy", approach: "Kadane's algorithm: track current sum, reset when negative.", solution: `function maxSubArray(nums) {\n  let max = nums[0], curr = nums[0];\n  for (let i = 1; i < nums.length; i++) {\n    curr = Math.max(nums[i], curr + nums[i]);\n    max = Math.max(max, curr);\n  }\n  return max;\n}`, complexity: "Time: O(n), Space: O(1)" },
  { problem: "Rotting Oranges (LeetCode 994)", difficulty: "Medium", approach: "BFS from all rotten oranges simultaneously. Count levels (minutes).", solution: `function orangesRotting(grid) {\n  const queue = [];\n  let fresh = 0;\n  for (let r = 0; r < grid.length; r++)\n    for (let c = 0; c < grid[0].length; c++) {\n      if (grid[r][c] === 2) queue.push([r, c, 0]);\n      else if (grid[r][c] === 1) fresh++;\n    }\n  let minutes = 0;\n  while (queue.length) {\n    const [r, c, t] = queue.shift();\n    minutes = Math.max(minutes, t);\n    for (const [dr, dc] of [[0,1],[0,-1],[1,0],[-1,0]]) {\n      const nr = r+dr, nc = c+dc;\n      if (nr >= 0 && nr < grid.length && nc >= 0 && nc < grid[0].length && grid[nr][nc] === 1) {\n        grid[nr][nc] = 2; fresh--; queue.push([nr, nc, t+1]);\n      }\n    }\n  }\n  return fresh === 0 ? minutes : -1;\n}`, complexity: "Time: O(M*N), Space: O(M*N)" },
  { problem: "Add and Search Word (LeetCode 211)", difficulty: "Medium", approach: "Trie with DFS for '.' wildcards.", solution: `class WordDictionary {\n  constructor() { this.root = {}; }\n  addWord(word) {\n    let node = this.root;\n    for (const c of word) { if (!node[c]) node[c] = {}; node = node[c]; }\n    node.end = true;\n  }\n  search(word) {\n    const dfs = (node, i) => {\n      if (i === word.length) return !!node.end;\n      if (word[i] === '.') {\n        for (const key in node)\n          if (dfs(node[key], i + 1)) return true;\n        return false;\n      }\n      return node[word[i]] ? dfs(node[word[i]], i + 1) : false;\n    };\n    return dfs(this.root, 0);\n  }\n}`, complexity: "Time: O(26^m) worst dot, Space: O(N*L)" },
];
